const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.arrow}</svg>`;
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
const imgBase='assets/';
const products=[
{slug:'agency-starter',name:'Agency Starter',type:'Template',desc:'Studio website',price:79,tool:'Framer',image:'fVGivzFXQoz0zOnsl0jG4H8auQI.jpg',fresh:true,copy:'A considered starting point for independent studios. Give your work room to breathe with confident typography, thoughtful layouts, and a clear path to getting in touch.'},
{slug:'studio-folio',name:'Studio Folio',type:'Template',desc:'Portfolio site',price:69,tool:'Framer',image:'dxjqn8XQifGPfW3axanUsDTxKR0.jpg',copy:'A quiet, editorial portfolio that puts your projects first. Built around generous spacing, beautiful imagery, and the small details that make a lasting impression.'},
{slug:'motion-blocks',name:'Motion Blocks',type:'Component',desc:'Scroll effects',price:29,tool:'Framer',image:'CO5pN4LUSwciGPz6IQtZEtOTVc.jpg',copy:'A collection of restrained motion ideas for more expressive websites. Subtle reveals and transitions that guide attention without getting in the way.'},
{slug:'core-ui-kit',name:'Core UI Kit',type:'UI Kit',desc:'Interface kit',price:49,tool:'Figma',image:'gaxRdhHkdMqfvaZlOFyUCSmGPcw.jpg',copy:'A thoughtful foundation for your next interface. Start with a coherent visual language and spend your energy on what makes your product useful.'},
{slug:'form-kit',name:'Form Kit',type:'Component',desc:'Website forms',price:19,tool:'Framer',image:'HvrZcpa2rvnSDCNaeekAMGUu0yc.jpg',copy:'Simple forms that feel effortless. A practical starting point for clear labels, comfortable inputs, helpful feedback, and confident next steps.'},
{slug:'wireframe-kit',name:'Wireframe Kit',type:'UI Kit',desc:'Fast wireframes',price:39,tool:'Figma',image:'beolGvIyj2vUPdLyziDvJbBCKU.jpg',copy:'Find the right structure before the fine details. A clean wireframing collection to explore ideas, map a flow, and move from a blank canvas to a clear direction.'}
];
const pages=[['home','Home'],['about','About'],['work','Work'],['services','Services'],['store','Store'],['blog','Blog']];
const $=s=>document.querySelector(s), escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let category='All', view=read('sidefolio-view','grid'), saved=read('sidefolio-saved',[]), savedOnly=false, toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function setTheme(theme){document.body.classList.toggle('dark',theme==='dark');save('sidefolio-theme',theme);document.querySelectorAll('[data-theme]').forEach(b=>{const selected=b.dataset.theme===theme;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)});$('meta[name="theme-color"]').content=theme==='dark'?'#141416':'#f6f6f8'}
setTheme(read('sidefolio-theme','light'));
$('#navigation').innerHTML=pages.map(([slug,name])=>`<a href="#/${slug}" data-page="${slug}">${icon(slug)}${name}</a>`).join('');
function card(p){return `<article class="product" data-product="${p.slug}"><a class="product-media" href="#/store/${p.slug}" aria-label="Explore ${p.name}"><img src="${imgBase+p.image}?scale-down-to=1024" alt="${p.name} preview" loading="lazy" width="1000" height="747"><div class="product-badges"><span class="badge">${toolIcon(p.tool)} ${p.tool}</span>${p.fresh?'<span class="badge new">New</span>':''}</div><span class="media-action">${icon('arrow')}</span></a><div class="product-info"><div><h2><a href="#/store/${p.slug}">${p.name}</a></h2><div class="product-meta">${p.type} <span aria-hidden="true">·</span> ${p.desc}</div></div><a class="price" href="#/store/${p.slug}" aria-label="${p.name}, ${p.price} dollars">$${p.price}</a></div></article>`}
const hero=(label,title,sub)=>`<section class="hero"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${sub}</p></section>`;
function cta(){return `<section class="cta-section"><div><h2>Let’s work together.</h2><p>Tell me about your project and let’s find a thoughtful way forward.</p><div class="cta-actions"><a href="#/contact" class="primary">Start a project <span>↗</span></a><button class="text-button" data-copy>Copy email&nbsp; ↗</button></div><div class="cta-note"><span class="status-dot"></span>Available for work <span>·</span> Open to good conversations</div></div><div class="newsletter"><h3>Notes on design & business.</h3><p>Thoughts from the process. New tools from the studio.<br>A little inspiration, at your own pace.</p><form class="subscribe-form"><input type="email" required aria-label="Email for product updates" placeholder="Your email address"><button type="submit">Notify me&nbsp; ↗</button></form><p class="privacy-note">Demo: your email stays in this browser. <a href="#/legals/privacy-policy">Privacy policy</a></p></div></section>`}
function store(){return `<section class="hero"><a href="#/store/agency-starter" class="new-pill"><span>New release</span>Meet Agency Starter <b>↗</b></a><h1>Tools from<br><em>my own workflow.</em></h1><p>Templates, components and kits I built for client work,<br class="desktop-break"> ready for yours.</p><span class="hero-index">THE COLLECTION / 06</span></section><section aria-label="Product collection"><div class="toolbar"><div class="filters" role="group" aria-label="Product category">${['All','Template','Component','UI Kit'].map(c=>`<button data-category="${c}" class="${c===category?'active':''}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="toolbar-right"><span class="collection-count" role="status"></span><div class="view-switch" role="group" aria-label="View style">${['grid','list'].map(v=>`<button data-view="${v}" class="${view===v?'active':''}" aria-label="${v} view" aria-pressed="${view===v}">${icon(v)}<span>${v[0].toUpperCase()+v.slice(1)}</span></button>`).join('')}</div></div></div><div class="collection ${view}" id="products"></div><div class="collection-end">${icon('check')} Thoughtfully made. Ready to make your own.</div></section>${cta()}`}
function updateProducts(){const list=products.filter(p=>(category==='All'||p.type===category)&&(!savedOnly||saved.includes(p.slug)));$('#products').innerHTML=list.length?list.map(card).join(''):`<div class="empty">${savedOnly?'No saved products yet. Open a product and save your favourites.':'Nothing in this collection yet.'}</div>`;if(savedOnly)$('#breadcrumb').textContent='Saved collection';settleCollection();updateCollectionCount();}
function detail(slug){const p=products.find(p=>p.slug===slug);if(!p)return notFound();return `<a href="#/store" class="detail-back">${icon('back')}Back to the collection</a><div class="detail-layout"><div><button class="image-preview" data-preview="${p.slug}" aria-label="Enlarge ${p.name} preview" style="padding:0;width:100%"><img class="detail-image" src="${imgBase+p.image}?scale-down-to=2048" alt="${p.name} preview"></button></div><div class="detail-copy"><span class="badge">${p.tool} / ${p.type}</span><h1>${p.name}</h1><p>${p.copy}</p><ul><li>A starting point for your next project</li><li>Designed to be made your own</li><li>${p.desc} · ${p.tool}</li></ul><button class="primary" data-preview="${p.slug}">Explore preview <span>↗</span></button><div class="detail-tools"><button class="secondary" aria-pressed="${saved.includes(p.slug)}" data-save="${p.slug}">${saved.includes(p.slug)?'♥ Saved':'♡ Save for later'}</button><button class="secondary" data-copy-product="${p.slug}">Copy link ↗</button></div><p class="demo-note">Reference price: $${p.price}. This is a design demonstration; product files and checkout are not connected.</p></div></div><h2 class="section-heading">More from the collection.</h2><div class="collection">${products.filter(x=>x.slug!==slug).slice(0,2).map(card).join('')}</div><div style="height:50px"></div>${cta()}`}
function home(){return hero('Independent designer & creative partner','Thoughtful design.<br><em>Lasting impressions.</em>','A small independent studio for clear identities, considered websites, and digital experiences that feel effortless.')+`<a href="#/work" class="primary">Explore the work ↗</a><div style="height:50px"></div><h2 class="section-heading">A few things from the studio.</h2><div class="collection">${products.slice(0,2).map(card).join('')}</div><div style="height:50px"></div>${cta()}`}
function about(){return hero('A little introduction','Less noise.<br><em>More intention.</em>','Good design starts with listening. Then comes the careful work of making the complex feel simple.')+`<div class="article"><img class="portrait-large" src="${$('.identity img').src}" alt="Yasin Sarveghad"><h2>A considered approach.</h2><p>This Sidefolio reinterpretation explores an independent designer’s studio: thoughtful identities, expressive websites, and practical tools for fellow makers.</p><p>The work is guided by clarity, honest materials, and attention to the details people feel before they notice.</p><h2>Built around the essentials.</h2><p>Understand the problem. Find a clear direction. Make the experience useful, accessible, and a pleasure to return to.</p></div>${cta()}`}
function services(){const items=[['Brand direction','A clear foundation for how your brand looks, speaks, and feels.','Discovery · Visual direction · Identity'],['Web design','Thoughtful websites that balance personality with effortless navigation.','Structure · Interface design · Responsive layouts'],['Design systems','Coherent components that help your product feel consistent as it grows.','Foundations · Components · Documentation'],['Creative partnership','A focused design partner for the next chapter of your business.','Product thinking · Art direction · Ongoing design']];return hero('Ways to work together','Good ideas.<br><em>Thoughtfully made.</em>','From the first conversation to the smallest finishing detail. A focused set of services, shaped around your project.')+`<div class="info-grid">${items.map((x,i)=>`<article class="info-card"><span class="number">0${i+1} / SERVICE</span><h2>${x[0]}</h2><p>${x[1]}</p><p>${x[2]}</p><a href="#/contact" class="text-button">Let’s talk ↗</a></article>`).join('')}</div>${cta()}`}
function work(){return hero('Selected explorations','A place for<br><em>considered work.</em>','A closer look at the templates and interface explorations behind the collection.')+`<div class="collection">${products.slice(0,4).map(card).join('')}</div><div style="height:60px"></div>${cta()}`}
const articles=[{slug:'less-but-considered',title:'Less, but more considered.',tag:'Design philosophy',body:'Removing an element is easy. Knowing what deserves to stay takes attention. A simpler interface should make the next step clearer, preserve useful context, and give the important things enough room to be understood.'},{slug:'motion-with-purpose',title:'Motion should make things clearer.',tag:'Interaction design',body:'The best transitions explain a relationship: where a panel came from, which state changed, and what happens next. Keep feedback immediate, movement restrained, and controls responsive even while a transition is running.'},{slug:'room-to-breathe',title:'Giving an interface room to breathe.',tag:'Visual craft',body:'Space creates relationships. A small gap connects a label to its control; a larger gap separates one idea from the next. Start with the content, build a consistent rhythm, and test it on the smallest screen.'}];
function blog(){return hero('Notes from the studio','A few thoughts.<br><em>A clearer perspective.</em>','Short notes on design, interaction, and the details that make a difference.')+`<div class="info-grid">${articles.map(a=>`<a class="info-card" href="#/blog/${a.slug}"><div class="eyebrow">${a.tag}</div><h2>${a.title}</h2><p>${a.body.slice(0,120)}…</p><span class="text-button">Read the note ↗</span></a>`).join('')}</div>${cta()}`}
function contact(){return hero('Start a conversation','Something good<br><em>starts here.</em>','A new website, a clearer identity, or an idea worth exploring.<br>Tell me what you have in mind.')+`
<section class="contact-layout" aria-label="Start a project">
  <aside class="contact-aside">
    <div class="contact-person"><span class="avatar"><img src="assets/yasin-sarveghad.png" alt="Yasin Sarveghad"></span><div><strong>Yasin Sarveghad</strong><small><span class="status-dot"></span>Open to new projects</small></div></div>
    <h2>Good work starts<br>with a good conversation.</h2>
    <p>A few details are all we need to get started. There’s room to figure out the rest together.</p>
    <button class="contact-email" data-copy>${icon('mail')}Copy email address <span>↗</span></button>
    <div class="aside-rule"></div>
    <div class="contact-steps"><div class="process-step"><span>01</span>A little about your idea.</div><div class="process-step"><span>02</span>A conversation about the direction.</div><div class="process-step"><span>03</span>A clear, considered next step.</div></div>
  </aside>
  <form class="contact-form">
    <div class="form-heading"><h2>A little about your project.</h2><span>About two minutes</span></div>
    <div class="form-row"><label>Your name<input name="name" required maxlength="100" autocomplete="name" placeholder="Your name"></label><label>Email address<input name="email" type="email" required maxlength="200" autocomplete="email" placeholder="you@studio.com"></label></div>
    <div class="form-row"><label>What do you need?<select name="service"><option>Web design</option><option>Brand direction</option><option>Design system</option><option>Creative partnership</option><option>Something else</option></select></label><label>Project budget<select name="budget"><option>Let’s discuss</option><option>$1,000–$5,000</option><option>$5,000–$10,000</option><option>$10,000+</option></select></label></div>
    <label>A little about your project<textarea name="message" required maxlength="2000" placeholder="What would you love to create?" aria-describedby="project-hint"></textarea><span class="field-hint" id="project-hint"><span>Your idea, goals, and a rough timeline.</span><output id="message-count">0 / 2,000</output></span></label>
    <button type="submit" class="primary">Prepare email draft <span>↗</span></button>
    <p class="demo-note">Opens your email app. Nothing is sent automatically.<br>The recipient is the address used in the reference template.</p>
  </form>
</section>`}
function legal(slug){const title={'privacy-policy':'Privacy Policy','terms-of-service':'Terms of Service','cookie-policy':'Cookie Policy'}[slug];if(!title)return notFound();const text=slug==='privacy-policy'?'This demonstration has no account system or application server. Theme preferences, saved product identifiers, and the optional notification email are stored locally in your browser. Product preview images are bundled locally. External social and email links open only when selected.':slug==='cookie-policy'?'This demonstration does not set application cookies. It uses browser local storage to remember the selected theme, view preference, saved products, and an optional notification email. You can clear these settings using the button below.':'This is an independent design demonstration inspired by the Sidefolio reference template. Product previews and reference prices are displayed for demonstration. No purchases, product downloads, newsletter delivery, or client bookings are processed here. The added editorial and service pages are illustrative demo content.';return hero('The small print',title,'Information about this demonstration.')+`<article class="article"><p>${text}</p><h2>Your choices.</h2><p>You can remove locally stored preferences at any time. Contact forms open your email application and leave sending the message to you.</p><button class="secondary" data-clear>Clear local preferences</button></article>`}
function notFound(){return hero('404','A quiet dead end.','That page isn’t in this collection.')+'<a class="primary" href="#/store">Back to the store ↗</a><div style="height:150px"></div>'}
function render(){const route=location.hash.replace(/^#\/?/,'')||'store';const [section,slug]=route.split('/');document.title=`${slug?products.find(p=>p.slug===slug)?.name||'Notes':section.charAt(0).toUpperCase()+section.slice(1)} — Yasin Sarveghad`;$('#breadcrumb').textContent=section==='store'?(slug?'The collection / '+(products.find(p=>p.slug===slug)?.name||'Product'):'The collection'):section.charAt(0).toUpperCase()+section.slice(1);document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===section);if(a.dataset.page===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const contactLink=document.querySelector('.contact-link');contactLink.classList.toggle('active',section==='contact');if(section==='contact')contactLink.setAttribute('aria-current','page');else contactLink.removeAttribute('aria-current');let html;if(section==='store')html=slug?detail(slug):store();else if(section==='home')html=home();else if(section==='about')html=about();else if(section==='work')html=work();else if(section==='services')html=services();else if(section==='contact')html=contact();else if(section==='blog'){const a=articles.find(a=>a.slug===slug);html=slug?(a?hero(a.tag,a.title,'Studio note · Illustrative editorial content')+`<article class="article"><p>${a.body}</p><a class="text-button" href="#/blog">← All notes</a></article>${cta()}`:notFound()):blog()}else if(section==='legals')html=legal(slug);else html=notFound();$('#main').innerHTML=`<div class="page-enter">${html}</div>`;if(section==='store'&&!slug)updateProducts();$('#footer').innerHTML=`<span>© 2026 Yasin Sarveghad <span style="opacity:.55">/ Sidefolio reimagined</span></span><div class="legal-links"><a href="#/legals/privacy-policy">Privacy Policy</a><a href="#/legals/terms-of-service">Terms of Service</a><a href="#/legals/cookie-policy">Cookie Policy</a></div><button data-top aria-label="Back to top">↑</button>`;icons();setMobileMenu(false,false);updateSavedBadge();setupPageMotion();setupContactDraft();window.scrollTo({top:0,behavior:'instant'});if(keyboardNavigation)$('#main').focus({preventScroll:true});}
async function copy(value,message){try{await navigator.clipboard.writeText(value);toast(message)}catch{toast('Clipboard unavailable. Use your browser’s copy command.')}}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main').focus();return}const b=e.target.closest('button');if(!b)return;if(b.dataset.theme)setTheme(b.dataset.theme);if(b.matches('.menu-toggle'))setMobileMenu(!$('#sidebar').classList.contains('open'));if(b.dataset.category){captureCollection();category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});updateProducts()}if(b.dataset.view){captureCollection();view=b.dataset.view;save('sidefolio-view',view);document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$('#products').className='collection '+view;settleCollection()}if(b.hasAttribute('data-copy'))copy('hello@alexmorgan.studio','Reference email copied');if(b.dataset.copyProduct)copy(location.href,'Product link copied');if(b.dataset.save){const slug=b.dataset.save;saved=saved.includes(slug)?saved.filter(s=>s!==slug):[...saved,slug];save('sidefolio-saved',saved);b.textContent=saved.includes(slug)?'♥ Saved':'♡ Save for later';b.setAttribute('aria-pressed',saved.includes(slug));updateSavedBadge();toast(saved.includes(slug)?'Saved to your collection':'Removed from saved products')}if(b.id==='saved-button'){savedOnly=!savedOnly;category='All';if(location.hash==='#/store'||!location.hash)render();else location.hash='/store';b.setAttribute('aria-pressed',savedOnly);toast(savedOnly?'Showing your saved collection':'Showing the full collection')}if(b.dataset.preview){const p=products.find(p=>p.slug===b.dataset.preview);$('#preview-content').innerHTML=`<h2 class="section-heading">${p.name}</h2><img src="${imgBase+p.image}?scale-down-to=2048" alt="${p.name} enlarged preview"><p class="demo-note">Reference product preview · ${p.tool} · $${p.price}</p>`;$('#preview-dialog').showModal()}if(b.matches('.close-modal'))$('#preview-dialog').close();if(b.matches('.search-trigger'))openSearch();if(b.hasAttribute('data-top'))window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(b.hasAttribute('data-clear')){['sidefolio-theme','sidefolio-view','sidefolio-saved','sidefolio-interest'].forEach(k=>localStorage.removeItem(k));saved=[];view='grid';savedOnly=false;setTheme('light');toast('Local preferences cleared')}});
document.addEventListener('submit',e=>{if(e.target.matches('.subscribe-form')){e.preventDefault();save('sidefolio-interest',e.target.querySelector('input').value);e.target.querySelector('button').textContent='Saved ✓';toast('Saved in this browser. No subscription was sent.')}if(e.target.matches('.contact-form')){e.preventDefault();const d=new FormData(e.target);const body=`Name: ${d.get('name')}\nEmail: ${d.get('email')}\nService: ${d.get('service')}\nBudget: ${d.get('budget')}\n\n${d.get('message')}`;const a=document.createElement('a');a.href='mailto:hello@alexmorgan.studio?subject='+encodeURIComponent('Project enquiry — '+d.get('name'))+'&body='+encodeURIComponent(body);a.click();toast('Email draft requested in your email app.')}});
function openSearch(){setMobileMenu(false,false);if($('#preview-dialog').open)$('#preview-dialog').close();$('#search-dialog').showModal();$('#global-search').value='';search('');$('#global-search').focus()}
function search(q){const items=[...pages.map(([slug,name])=>({name,href:'#/'+slug,type:'Page'})),...products.map(p=>({name:p.name,href:'#/store/'+p.slug,type:p.type})),...articles.map(a=>({name:a.title,href:'#/blog/'+a.slug,type:'Note'}))].filter(x=>(x.name+' '+x.type).toLowerCase().includes(q.trim().toLowerCase()));$('#search-results').innerHTML=items.length?items.map(x=>`<a href="${x.href}"><span>${escapeHTML(x.name)}</span><small>${x.type} ↗</small></a>`).join(''):'<div class="empty">No results. Try “template” or “studio”.</div>';searchIndex=-1;$('#search-status').textContent=items.length+' result'+(items.length===1?'':'s');}
$('#global-search').addEventListener('input',e=>search(e.target.value));
$('#global-search').addEventListener('keydown',e=>{
  const links=[...document.querySelectorAll('#search-results a')];
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){
    e.preventDefault();if(!links.length)return;
    searchIndex=searchIndex<0?(e.key==='ArrowDown'?0:links.length-1):(searchIndex+(e.key==='ArrowDown'?1:-1)+links.length)%links.length;
    links.forEach((a,i)=>a.classList.toggle('search-active',i===searchIndex));
    links[searchIndex].scrollIntoView({block:'nearest'});
    $('#search-status').textContent=links[searchIndex].innerText.replace('↗','');
  }
  if(e.key==='Enter'){e.preventDefault();const a=links[Math.max(0,searchIndex)];if(a){location.hash=a.getAttribute('href');$('#search-dialog').close()}}
});
$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))$('#search-dialog').close()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').open?$('#search-dialog').close():openSearch()}});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
// Edition 02. Motion remains optional and has no third-party runtime.
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
const compactLayout=matchMedia('(max-width:760px)');
let keyboardNavigation=false,searchIndex=-1,collectionBefore=null,revealObserver=null;
const shortcutLabel=/Mac|iPhone|iPad/.test(navigator.platform)?'⌘ K':'Ctrl K';document.querySelector('.search-trigger kbd').textContent=shortcutLabel;
document.addEventListener('keydown',e=>{if(!['Meta','Control','Shift','Alt'].includes(e.key)){keyboardNavigation=true;document.body.classList.add('keyboard-nav')}},true);
document.addEventListener('pointerdown',()=>{keyboardNavigation=false;document.body.classList.remove('keyboard-nav')},true);
function toolIcon(name){return name==='Framer'?'<svg viewBox="0 0 12 18" aria-hidden="true"><path d="M1 1h10v5H6l5 5H6v6l-5-5V7h5L1 2z"/></svg>':'<svg viewBox="0 0 12 18" aria-hidden="true"><rect x="1" y="1" width="10" height="5" rx="2.5"/><rect x="1" y="6" width="5" height="5" rx="2.5"/><circle cx="8.5" cy="8.5" r="2.5"/><path d="M6 11H3.5A2.5 2.5 0 1 0 6 13.5z"/></svg>'}
function captureCollection(){
  const grid=$('#products');if(!grid)return;
  const cards=[...grid.querySelectorAll('.product')];
  collectionBefore=new Map(cards.map(el=>[el.dataset.product,el.getBoundingClientRect()]));
  cards.forEach(el=>el.getAnimations().forEach(a=>a.cancel()));
}
function settleCollection(){
  if(!collectionBefore)return;
  const old=collectionBefore;collectionBefore=null;
  if(reducedMotion.matches||keyboardNavigation)return;
  const easing=getComputedStyle(document.documentElement).getPropertyValue('--ease').trim();
  document.querySelectorAll('#products .product').forEach(el=>{
    const before=old.get(el.dataset.product),after=el.getBoundingClientRect();
    const dx=before?before.left-after.left:0,dy=before?before.top-after.top:6;
    el.animate([{transform:`translate(${dx}px,${dy}px)`,opacity:before?0.8:0},{transform:'translate(0,0)',opacity:1}],{duration:240,easing});
  });
}
function updateCollectionCount(){const count=$('.collection-count');if(count)count.textContent=document.querySelectorAll('#products .product').length+' items'}
function updateSavedBadge(){const b=$('#saved-button');b.setAttribute('aria-label',`Saved products, ${saved.length} saved`);b.setAttribute('aria-pressed',savedOnly);b.innerHTML=icon('heart')+(saved.length?`<span class="saved-count" aria-hidden="true">${saved.length}</span>`:'')}
function setMobileMenu(open,restore=true){
  const sidebar=$('#sidebar'),toggle=$('.menu-toggle');const wasOpen=sidebar.classList.contains('open');
  sidebar.classList.toggle('open',open);toggle.setAttribute('aria-expanded',open);toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');
  toggle.innerHTML=icon(open?'close':'menu');$('.workspace').inert=open;document.body.style.overflow=open?'hidden':'';
  if(!open&&wasOpen&&restore)toggle.focus({preventScroll:true});
}
compactLayout.addEventListener('change',()=>setMobileMenu(false,false));
document.addEventListener('keydown',e=>{
  if(!$('#sidebar').classList.contains('open')||!compactLayout.matches||$('dialog[open]'))return;
  if(e.key==='Escape'){e.preventDefault();setMobileMenu(false);return}
  if(e.key==='Tab'){
    const controls=[...$('#sidebar').querySelectorAll('a,button')].filter(el=>el.getClientRects().length);
    const first=controls[0],last=controls.at(-1);
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  }
});
function setupPageMotion(){
  revealObserver?.disconnect();
  if(reducedMotion.matches||keyboardNavigation||!('IntersectionObserver' in window))return;
  revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
    if(entry.isIntersecting){entry.target.classList.remove('reveal-pending');revealObserver.unobserve(entry.target)}
  }),{threshold:0.08});
  document.querySelectorAll('.product,.info-card,.cta-section').forEach(el=>{
    if(el.getBoundingClientRect().top>innerHeight+20){el.classList.add('reveal-ready','reveal-pending');revealObserver.observe(el)}
  });
}
reducedMotion.addEventListener('change',()=>{
  revealObserver?.disconnect();document.querySelectorAll('.reveal-pending').forEach(el=>el.classList.remove('reveal-pending'));
  if(reducedMotion.matches)document.getAnimations().forEach(a=>a.cancel());
});
// Keep an unfinished contact draft only in memory; it never leaves this page.
let contactDraft={};
function setupContactDraft(){
  const form=$('.contact-form');if(!form)return;
  Object.entries(contactDraft).forEach(([key,value])=>{if(form.elements[key])form.elements[key].value=value});
  const update=()=>{const message=form.elements.message.value;$('#message-count').textContent=message.length.toLocaleString('en-US')+' / 2,000';contactDraft=Object.fromEntries(new FormData(form))};
  form.addEventListener('input',update);form.addEventListener('change',update);update();
}

window.addEventListener('hashchange',render);render();
